let phase = 0, amplitude = 0.7;
const bend = new CustomModifier(contours => contours.map(contour => {
  const result = contour.slice();
  for (let i = 0; i < result.length; i += 2) {
    result[i + 1] += amplitude * Math.sin(result[i] + phase);
  }
  return result;
}), 'Wave');
const deformed = new Path('M -3 0 Q -1.5 0 0 0 Q 1.5 0 3 0', {
  fill: Color.NONE, stroke: hex('#38bdf8'), strokeWidth: 0.1, modifiers: [bend]
});
this.add(deformed);

this.always((_time, dt) => {
  phase += dt / 1000;
  bend.invalidate();
  this.invalidate();
});
